import type { AutoMovieHumanLoftFrame } from "../lofting/AutoMovieHumanLoftFrame";
import type { AutoMovieHumanLoftParameter } from "../lofting/AutoMovieHumanLoftParameter";
import type { IAutoMovieHumanRelief } from "./IAutoMovieHumanRelief";

/**
 * A chain stored as its key sections only.
 *
 * Every section between two keys is generated by
 * {@link AutoMovieHumanFeatureChain.compose}: each control-point coordinate
 * follows the natural cubic spline through the keys, the interpolant of least
 * bending energy, so the skin between two keys is smooth by construction.
 * Transforming a key moves every section it governs.
 *
 * A chain with an {@link anchor} is a module in its own frame
 * (hierarchical modelling: Hughes et al. 2014, Computer Graphics: Principles
 * and Practice, 3rd ed., ch. 6): every key carries its `frame`, and its
 * stations, key frames, cap pole and relief axes are read in the anchor's
 * frame, so a transform of the anchor carries the whole module. A chain
 * without one stores the world coordinates of the world-height calibration.
 */
export interface IAutoMovieHumanFeatureChain {
  /** Name of the chain it generates; unique across the calibration. */
  name: string;

  /** Number of periodic B-spline control points of every section, N. */
  order: number;

  /** Phase correspondence rule of the generated chain. */
  rule: AutoMovieHumanLoftParameter.Rule;

  /** Number of uniform phases of the generated chain's own rings. */
  samples: number;

  /** Key sections by strictly increasing station, at least two. */
  keys: IAutoMovieHumanFeatureChain.IKey[];

  /** Reliefs over the chain's surface; absent means none. */
  reliefs?: IAutoMovieHumanRelief[];

  /**
   * Ends whose key is shared with a neighbouring chain that owns it: the key
   * is copied from the owner's composed end layer, and the interval ending
   * there takes the owner's first and second station derivatives, so the
   * join is C2. Absent ends are free.
   */
  ends?: {
    /** The bottom key's owner. */
    bottom?: IAutoMovieHumanFeatureChain.IShare;

    /** The top key's owner. */
    top?: IAutoMovieHumanFeatureChain.IShare;
  };

  /**
   * Cap closing one end of this chain past its end key: the keys beyond
   * `cap.from` on the cap's side are the cap's, their planes set by the
   * cap's formula; absent for a chain without a cap.
   */
  cap?: IAutoMovieHumanFeatureChain.ICap;

  /**
   * The module's frame: the bind frame of the joint its axis begins at, or
   * a child frame of its parent's anchor for a module with no bind joint.
   * Present, every key carries `frame`, and stations, key frames, the pole
   * and relief axes are in the anchor's coordinates; absent, they are world
   * coordinates.
   */
  anchor?: IAutoMovieHumanFeatureChain.IAnchor;
}
export namespace IAutoMovieHumanFeatureChain {
  /** The owner of a shared key. */
  export interface IShare {
    /** Owning chain's name. */
    owner: string;

    /** The owner's end whose key is shared. */
    end: "bottom" | "top";
  }

  /**
   * A cap continuing its chain past the end key: its angle theta from the
   * pole axis runs on from the end key's station `s_e` as
   * `s = s_e + sigma rho (pi / 2 - theta)`, sigma 1 for a top cap and -1 for
   * a bottom one, and its keys lie in planes parallel to the end key at
   * origins `C + rho cos(theta) n` (C the end key's origin, n its normal
   * pointing out of the base, or toward the pole when the end key is the
   * chain's only key before the cap, rho the pole's distance from the end
   * plane). The pole key, every control point at the pole, is the chain's
   * end key on the cap's side, at `s_e + sigma rho pi / 2`.
   */
  export interface ICap {
    /** The chain's end the cap closes. */
    end: "bottom" | "top";

    /** Station of the end key, the last key of the base before the cap, mm. */
    from: number;

    /** The pole, mm, in the anchor's coordinates for an anchored chain. */
    pole: [number, number, number];
  }

  /** One key section. */
  export interface IKey {
    /**
     * Station of the section along the chain, mm: arc length along the
     * module's axis from its anchor joint for an anchored chain, the world
     * height of a horizontal one otherwise.
     */
    station: number;

    /**
     * Section plane, in the anchor's coordinates for an anchored chain,
     * which requires it; absent on an unanchored chain means horizontal at
     * the station.
     */
    frame?: AutoMovieHumanLoftFrame.IFrame;

    /**
     * Control points `[x_0 .. x_{N-1}, z_0 .. z_{N-1}]` in the section plane,
     * mm, the layout of `AutoMovieHumanSplineCurve`.
     */
    coefficients: number[];
  }

  /**
   * A module's frame, a rigid frame written as {@link AutoMovieHumanLoftFrame.IFrame}:
   * a point `(x, y, z)` of the frame's coordinates lies at
   * `origin + x u + y (v x u) + z v`.
   */
  export type IAnchor = IJointAnchor | IChildAnchor;

  /** The anchor of a module whose axis begins at a bind joint. */
  export interface IJointAnchor {
    /** Source name of the bind joint. */
    joint: string;

    /**
     * The joint's registered bind frame in world mm: the orthogonal polar
     * factor of its bind affine and its bind translation.
     */
    frame: AutoMovieHumanLoftFrame.IFrame;

    /** The module's named axes, unit vectors in the anchor's coordinates. */
    axes: IAxes;

    /** Further named frames in the anchor's coordinates, such as the head's `frankfurt`; absent means none. */
    frames?: Record<string, AutoMovieHumanLoftFrame.IFrame>;

    /** The bind joints this module declares, each declared by one module only. */
    joints: IJoint[];
  }

  /** The anchor of a module with no bind joint: a child frame of its parent's anchor. */
  export interface IChildAnchor {
    /** Name of the parent chain whose anchor carries this frame. */
    parent: string;

    /** The child frame in the parent anchor's coordinates. */
    frame: AutoMovieHumanLoftFrame.IFrame;

    /** The module's named axes, unit vectors in the parent anchor's coordinates. */
    axes: IAxes;
  }

  /**
   * A module's own directions: along its axis, toward its front (dorsal for
   * a hand, a foot, a digit or a toe, forward for the trunk and the head)
   * and lateral, `along x front`.
   */
  export interface IAxes {
    /** Tangent of the module's axis at its anchor. */
    along: [number, number, number];

    /** The module's front. */
    front: [number, number, number];

    /** `along x front`. */
    lateral: [number, number, number];
  }

  /** One declared bind joint. */
  export interface IJoint {
    /** Source name of the joint. */
    name: string;

    /** The joint's centre in the anchor's coordinates, mm. */
    point: [number, number, number];

    /**
     * Station of the joint's centre plane where it lies between the first
     * key and `cap.from`; absent beyond that range.
     */
    station?: number;
  }
}
